@page "/settings"
@using sv_7ffe516abf4c4b79bb2d0a094cbd31ba.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }

        @if (activeSection == "Profile")
        {
            <section class="settings-section">
                <h2>Profile Settings</h2>
                @if (profile is not null)
                {
                    <div class="avatar-area">
                        <img src="@editDisplayAvatarUrl" alt="Avatar" class="avatar-preview" />
                        <p class="avatar-url">@editDisplayAvatarUrl</p>
                    </div>
                    <div class="form-group">
                        <label for="displayName">Display Name</label>
                        <input id="displayName" type="text" @bind="editDisplayName" />
                    </div>
                    <div class="form-group">
                        <label for="email">Email</label>
                        <input id="email" type="email" @bind="editEmail" />
                    </div>
                    <div class="form-group">
                        <label for="bio">Bio</label>
                        <textarea id="bio" rows="4" @bind="editBio"></textarea>
                    </div>
                    <div class="form-group">
                        <label for="avatarUrl">Avatar URL</label>
                        <input id="avatarUrl" type="url" @bind="editDisplayAvatarUrl" />
                    </div>
                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                        <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Notifications")
        {
            <section class="settings-section">
                <h2>Notification Preferences</h2>
                @if (notifications is not null)
                {
                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Email Notifications</span>
                            <input type="checkbox" @bind="editEmailNotifications" class="toggle-switch" />
                        </label>
                        <label class="toggle-label">
                            <span>Push Notifications</span>
                            <input type="checkbox" @bind="editPushNotifications" class="toggle-switch" />
                        </label>
                        <label class="toggle-label">
                            <span>Weekly Digest</span>
                            <input type="checkbox" @bind="editWeeklyDigest" class="toggle-switch" />
                        </label>
                    </div>

                    <h3>Muted Channels</h3>
                    <div class="channel-list">
                        @foreach (var channel in allChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@IsChannelMuted(channel)"
                                       @onchange="(e) => ToggleChannelMute(channel, (bool)(e.Value ?? false))" />
                                <span>#@channel</span>
                            </label>
                        }
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
                    </div>
                }
            </section>
        }
        else if (activeSection == "Security")
        {
            <section class="settings-section">
                <h2>Security Settings</h2>
                @if (security is not null)
                {
                    <div class="expandable-panel">
                        <button class="panel-header" @onclick="TogglePasswordPanel">
                            <span>Change Password</span>
                            <span class="expand-icon">@(showPasswordPanel ? "▾" : "▸")</span>
                        </button>
                        @if (showPasswordPanel)
                        {
                            <div class="panel-body">
                                <div class="form-group">
                                    <label for="currentPassword">Current Password</label>
                                    <input id="currentPassword" type="password" @bind="currentPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="newPassword">New Password</label>
                                    <input id="newPassword" type="password" @bind="newPassword" />
                                </div>
                                <div class="form-group">
                                    <label for="confirmPassword">Confirm Password</label>
                                    <input id="confirmPassword" type="password" @bind="confirmPassword" />
                                </div>
                                @if (!string.IsNullOrEmpty(passwordError))
                                {
                                    <p class="error-text">@passwordError</p>
                                }
                                <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                            </div>
                        }
                    </div>

                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Two-Factor Authentication</span>
                            <span class="status-indicator @(security.TwoFactorEnabled ? "status-enabled" : "status-disabled")">
                                @(security.TwoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                            <input type="checkbox" checked="@security.TwoFactorEnabled" disabled class="toggle-switch" />
                        </label>
                    </div>

                    @if (security.LastPasswordChange.HasValue)
                    {
                        <p class="info-text">Last password change: @security.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                    }

                    <h3>Active Sessions</h3>
                    <table class="sessions-table">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in security.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session.Id != currentSessionId)
                                        {
                                            <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>

                    @if (showRevokeConfirmation && sessionToRevoke is not null)
                    {
                        <div class="modal-overlay" @onclick="CancelRevoke">
                            <div class="modal" @onclick:stopPropagation="true">
                                <h3>Confirm Session Revocation</h3>
                                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                                <div class="button-group">
                                    <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (activeSection == "Appearance")
        {
            <section class="settings-section">
                <h2>Appearance Settings</h2>
                @if (appearance is not null)
                {
                    <div class="form-group">
                        <label>Theme</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Light" checked="@(editTheme == "Light")" @onchange='() => editTheme = "Light"' /> Light
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="Dark" checked="@(editTheme == "Dark")" @onchange='() => editTheme = "Dark"' /> Dark
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="theme" value="System" checked="@(editTheme == "System")" @onchange='() => editTheme = "System"' /> System
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label>Font Size</label>
                        <div class="radio-group">
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Small" checked="@(editFontSize == "Small")" @onchange='() => editFontSize = "Small"' /> Small
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Medium" checked="@(editFontSize == "Medium")" @onchange='() => editFontSize = "Medium"' /> Medium
                            </label>
                            <label class="radio-label">
                                <input type="radio" name="fontSize" value="Large" checked="@(editFontSize == "Large")" @onchange='() => editFontSize = "Large"' /> Large
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="language">Language</label>
                        <select id="language" @bind="editLanguage">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                            <option value="Chinese">Chinese</option>
                        </select>
                    </div>

                    <div class="toggle-group">
                        <label class="toggle-label">
                            <span>Compact Mode</span>
                            <input type="checkbox" @bind="editCompactMode" class="toggle-switch" />
                        </label>
                    </div>

                    <h3>Live Preview</h3>
                    <div class="live-preview @GetPreviewClasses()">
                        <div class="preview-header">Preview Header</div>
                        <p class="preview-text">This is how your content will look with the selected settings.</p>
                        <div class="preview-card">
                            <strong>Sample Card</strong>
                            <p>Theme: @editTheme | Font: @editFontSize | Language: @editLanguage</p>
                        </div>
                    </div>

                    <div class="button-group">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                }
            </section>
        }
    </main>
</div>

