    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 6px;
    cursor: pointer;
}

.toggle-label span:first-child {
    flex: 1;
    font-weight: 500;
}

.toggle-switch {
    width: 20px;
    height: 20px;
    accent-color: #4f46e5;
}

