+.btn-secondary {
+    background: #e2e8f0;
+    color: #475569;
+}
+.btn-secondary:hover { background: #cbd5e1; }
+
+.btn-danger {
+    background: #dc2626;
+    color: #fff;
+}
+.btn-danger:hover { background: #b91c1c; }
+
+.btn-sm {
+    padding: 0.3rem 0.75rem;
+    font-size: 0.8rem;
+}
+
+/* Avatar */
+.avatar-area {
+    margin-bottom: 1.5rem;
+    display: flex;
+    align-items: center;
+    gap: 1rem;
+}
+
+.avatar-preview {
+    width: 80px;
+    height: 80px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #e2e8f0;
+}
+
+.avatar-url {
+    font-size: 0.8rem;
+    color: #64748b;
+    word-break: break-all;
+    max-width: 300px;
+}
+
+/* Toggle switches */
+.toggle-group {
+    display: flex;
+    flex-direction: column;
+    gap: 0.75rem;
+    margin-bottom: 1rem;
+}
+
+.toggle-label {
+    display: flex;
+    align-items: center;
+    gap: 0.75rem;
+    padding: 0.75rem 1rem;
+    background: #f8fafc;
+    border: 1px solid #e2e8f0;
+    border-radius: 6px;
+    cursor: pointer;
+}
+
+.toggle-label span:first-child {
+    flex: 1;
+    font-weight: 500;
+}
+
+.toggle-switch {
+    width: 20px;
+    height: 20px;
+    accent-color: #4f46e5;
+}
+
+/* Status indicator */
+.status-indicator {
+    font-size: 0.8rem;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    font-weight: 600;
+}
+
+.status-enabled {
+    background: #d1fae5;
+    color: #065f46;
+}
+
+.status-disabled {
+    background: #fee2e2;
+    color: #991b1b;
+}
+
+/* Channel list */
+.channel-list {
+    display: flex;
+    flex-direction: column;
+    gap: 0.5rem;
+}
+
+.channel-item {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+    padding: 0.5rem 0.75rem;
+    border: 1px solid #e2e8f0;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.channel-item:hover {
+    background: #f1f5f9;
+}
+
+/* Expandable panel */
+.expandable-panel {
+    border: 1px solid #e2e8f0;
+    border-radius: 6px;
+    margin-bottom: 1.5rem;
+    overflow: hidden;
+}
+
+.panel-header {
+    width: 100%;
+    padding: 0.75rem 1rem;
+    background: #f8fafc;
+    border: none;
+    cursor: pointer;
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    font-weight: 500;
+    font-size: 1rem;
+}
+
+.panel-header:hover { background: #f1f5f9; }
+
+.expand-icon { color: #64748b; }
+
+.panel-body {
+    padding: 1rem;
+    border-top: 1px solid #e2e8f0;
+}
+
+/* Error text */
+.error-text {
+    color: #dc2626;
+    font-size: 0.85rem;
+    margin: 0.5rem 0;
+}
+
+.info-text {
+    color: #64748b;
+    font-size: 0.9rem;
+    margin: 1rem 0;
+}
+
+/* Sessions table */
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    margin-top: 0.5rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e2e8f0;
+}
+
+.sessions-table th {
+    background: #f8fafc;
+    font-weight: 600;
+    color: #475569;
+    font-size: 0.85rem;
+    text-transform: uppercase;
+}
+
+.sessions-table tr:hover {
+    background: #f8fafc;
+}
+
+.current-badge {
+    font-size: 0.75rem;
+    background: #dbeafe;
+    color: #1d4ed8;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    font-weight: 600;
+}
+
+/* Modal */
+.modal-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0,0,0,0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.modal {
+    background: #fff;
+    padding: 2rem;
+    border-radius: 8px;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 20px 60px rgba(0,0,0,0.3);
+}
+
+.modal h3 {
+    margin-top: 0;
+}
+
+/* Radio group */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Live Preview */
+.live-preview {
+    border: 1px solid #e2e8f0;
+    border-radius: 8px;
+    padding: 1.5rem;
+    margin-top: 0.5rem;
+    transition: all 0.3s ease;
+}
+
+.preview-header {
+    font-weight: 600;
+    font-size: 1.1rem;
+    margin-bottom: 0.5rem;
+}
+
+.preview-card {
+    margin-top: 0.75rem;
+    padding: 0.75rem;
+    border: 1px solid #e2e8f0;
+    border-radius: 6px;
+    background: rgba(0,0,0,0.02);
+}
+
+.preview-card p {
+    margin: 0.25rem 0 0;
+    font-size: 0.85rem;
+    color: #64748b;
+}
+
+/* Theme previews */
+.preview-theme-light {
+    background: #ffffff;
+    color: #1e293b;
+}
+
+.preview-theme-dark {
+    background: #1e293b;
+    color: #f1f5f9;
+    border-color: #475569;
+}
+
+.preview-theme-dark .preview-card {
+    background: rgba(255,255,255,0.05);
+    border-color: #475569;
+}
+
+.preview-theme-dark .preview-card p {
+    color: #94a3b8;
+}
+
+.preview-theme-system {
+    background: linear-gradient(135deg, #ffffff 50%, #1e293b 50%);
+    color: #1e293b;
+}
+
+/* Font size previews */
+.preview-font-small { font-size: 0.8rem; }
+.preview-font-medium { font-size: 1rem; }
+.preview-font-large { font-size: 1.2rem; }
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.5rem;
+}
+
